import numpy as np
def read_xyz(p):
    L=open(p).read().splitlines(); n=int(L[0]); els=[]; xyz=[]
    for l in L[2:2+n]:
        s=l.split(); els.append(s[0]); xyz.append([float(x) for x in s[1:4]])
    return els,np.array(xyz)
els,xyz=read_xyz('opt1.xyz')
def d(i,j): return np.linalg.norm(xyz[i]-xyz[j])
print("Ir-P",d(0,31),"Ir-Cmethyl",d(0,26),"Ir-H",d(0,30))
print("Ir-ring", [round(d(0,r),3) for r in [1,2,3,4,5]])
# ring planarity: centroid of ring
cent=xyz[[1,2,3,4,5]].mean(0)
print("Ir-centroid",np.linalg.norm(cent-xyz[0]))
# P-ipso, P-H distances
print("P-ipso",d(31,32))
# find P hydrogens (atoms bonded to P in ligand: among ligand atoms 31..112, H near P)
for i in range(31,113):
    if els[i]=='H' and d(i,31)<1.6:
        print("P-H",i,round(d(i,31),3))
# check min interatomic (excluding bonds) roughly: shortest H...H between fragment(0..30) and ligand(31..)
mind=9; pair=None
for i in range(0,31):
    for j in range(31,113):
        dd=d(i,j)
        if dd<mind: mind=dd; pair=(els[i]+str(i),els[j]+str(j))
print("shortest frag-lig",mind,pair)
